public class G1MemoryTuneDemo {
    // Recommended production baseline flags for modern JVMs utilizing G1
    // -XX:+UseG1GC
    // -XX:MaxGCPauseMillis=200
    // -XX:InitiatingHeapOccupancyPercent=45
    // -XX:G1ReservePercent=15

    public static void main(String[] args) {
        System.out.println("G1 GC dynamically sizes regions based on heap capacity.");
        long maxMemory = Runtime.getRuntime().maxMemory();
        System.out.println("Max Heap: " + (maxMemory / (1024 * 1024)) + " MB");
    }
}
